  data = $fonjson${"slug": "fundamentals-of-nursing", "title": "Fundamentals of Nursing", "description": "This course introduces professional nursing roles, ethics, the nursing process, therapeutic communication, beginning assessment, infection prevention, hygiene and mobility, nutrition and elimination, medication safety, wound care, documentation, patient education, quality improvement, teamwork, and skills-lab readiness.", "topics": [{"id": "c8dacc45-cc13-40f8-aa9b-5f6e66b37c86", "type": "topic", "title": "Professional Nursing Roles, Scope, Ethics, and Accountability", "description": "Understand what professional nursing is, how scope and standards guide practice, and why ethics matters in every interaction.", "children": [{"id": "7f9d4667-2305-46ba-9183-4dcece2a73ed", "type": "subtopic", "title": "Professional identity", "description": "Students begin by seeing nursing as a disciplined, accountable profession, not only a list of tasks.", "children": [{"id": "dcef1470-a624-4a2c-bba6-a2e611738c02", "type": "concept", "title": "Professional role"}, {"id": "d1690441-76e4-4eba-80c1-841604e8f856", "type": "concept", "title": "Accountability"}, {"id": "9716c825-7808-42ed-b932-f8f9c03c6a3f", "type": "concept", "title": "Compassionate presence"}, {"id": "29e4dcef-f08a-41b3-822b-123f98799a92", "type": "concept", "title": "Lifelong learning"}]}, {"id": "67f4b06b-2536-41fa-9eb6-53af44566555", "type": "subtopic", "title": "Scope and standards", "description": "Scope and standards clarify what nurses are educated, authorized, and expected to do.", "children": [{"id": "a2c2a919-cc08-4366-aaff-0bbeca78916a", "type": "concept", "title": "Scope of practice"}, {"id": "aa723abc-3ca5-439c-8319-9fdfa3ecf485", "type": "concept", "title": "Standards of care"}, {"id": "d4dc66c1-b4b9-4f72-a7da-5c2d1e3583e4", "type": "concept", "title": "State nurse practice acts"}, {"id": "a00792a9-62fe-4a52-92d2-50d13558e03b", "type": "concept", "title": "Professional boundaries"}]}, {"id": "c86f5694-7b